type ModMetadata={category?:string;ownerProfileId?:string};
function readModMetadata():Record<string,ModMetadata>{try{const v=JSON.parse(localStorage.getItem('hf-mod-metadata-v1')||'{}');return v&&typeof v==='object'&&!Array.isArray(v)?v:{}}catch{return {}}}
