const uid=()=>`${Date.now()}-${Math.random().toString(36).slice(2)}`;
export default function App(){const [tab,setTab]=useState('Головна');const [achievementStats,setAchievementStats]=useState<AchievementStats>(emptyAchievements);const [language,setLanguage]=useState(localStorage.getItem('hellforge-language-major')||'uk');const [sortOpen,setSortOpen]=useState(false);const [theme,setTheme]=useState(localStorage.getItem('hellforge-theme-major')||'obsidian');const [lib,setLib]=useState<Library>(empty);const [error,setError]=useState('');const [notice,setNotice]=useState('');const [search,setSearch]=useState('');const [draft,setDraft]=useState<Profile|null>(null);const [logs,setLogs]=useState<string[]>([]);const [engines,setEngines]=useState<EngineInfo[]>([]);const [engineName,setEngineName]=useState('');const [busy,setBusy]=useState(false);const [installingEngine,setInstallingEngine]=useState<string|null>(null);const [sort,setSort]=useState('name');const [newGroup,setNewGroup]=useState('');const [renameTarget,setRenameTarget]=useState<{kind:'mod'|'map';id:string;name:string}|null>(null);const [renameValue,setRenameValue]=useState('');const [deleteTarget,setDeleteTarget]=useState<{kind:'game'|'mod'|'map'|'profile';id:string;name:string}|null>(null);const [sgKey,setSgKey]=useState('');const [wadInfo,setWadInfo]=useState<{name:string;format:string;lumps:number;maps:string[];titlepic:boolean}|null>(null);const [history,setHistory]=useState<{profileId:string;startedAt:string;seconds:number;exitCode:number|null}[]>([]);const [historyProfile,setHistoryProfile]=useState('');const [compact,setCompact]=useState(false);const [useGroups,setUseGroups]=useState(localStorage.getItem('hf-use-groups')!=='false');const [obsidianExe,setObsidianExe]=useState(localStorage.getItem('hf-obsidian-exe')||'');const [obsidianName,setObsidianName]=useState('Generated DOOM Map');const [obsidianBusy,setObsidianBusy]=useState(false);const [obsidianSettings,setObsidianSettings]=useState({game:'doom2',length:'single',theme:'original',outdoors:'mixed',bosses:'medium',caves:'mixed',liquids:'mixed',hallways:'mixed',teleporters:'mixed',steepness:'mixed',health:'normal',ammo:'normal',weapons:'normal',items:'normal',secrets:'mixed',float_size:'36',float_mons:'1',float_strength:'1'});const [modMetadata,setModMetadata]=useState<Record<string,ModMetadata>>(readModMetadata);const [modCategories,setModCategories]=useState<string[]>(readModCategories);const [modGroupView,setModGroupView]=useState(localStorage.getItem('hf-mod-group-view')!=='false');const [modFilter,setModFilter]=useState('Усі');const [modEditorFilter,setModEditorFilter]=useState('Усі');const [modEditorSearch,setModEditorSearch]=useState('');const [newModCategory,setNewModCategory]=useState('');const [editingModCategory,setEditingModCategory]=useState('');const [editedModCategoryName,setEditedModCategoryName]=useState('');const [selectedMods,setSelectedMods]=useState<string[]>([]);const [dragging,setDragging]=useState(false);const [launch,setLaunch]=useState<{id:string;state:string;detail?:string}|null>(null);
const updateModMetadata=(id:string,patch:ModMetadata)=>setModMetadata(prev=>{const next={...prev,[id]:{...prev[id],...patch}};localStorage.setItem('hf-mod-metadata-v1',JSON.stringify(next));return next});
const updateModCategories=(values:string[])=>{setModCategories(values);localStorage.setItem('hf-mod-categories-v1',JSON.stringify(values))};
const visibleGlobalMods=lib.mods.filter(m=>!modMetadata[m.id]?.ownerProfileId||!lib.profiles.some(p=>p.id===modMetadata[m.id]?.ownerProfileId));
const addPrivateMod=()=>action(async()=>{if(!draft)return;const path=await pick([{name:'Mod files',extensions:['wad','pk3','pk7','zip']}]);if(!path)return;const before=new Set(lib.mods.map(m=>m.id));const updated=await call<Library>('import_profile_mod',{path,profileId:draft.id});const added=updated.mods.find(m=>!before.has(m.id));if(!added)throw Error(t('Не вдалося визначити імпортований мод'));if(before.has(added.id)&&!draft.modIds.includes(added.id))throw Error(t('Цей файл уже є у бібліотеці. Додай його через ліву панель.'));if(modMetadata[added.id]?.ownerProfileId&&modMetadata[added.id].ownerProfileId!==draft.id)throw Error(t('Цей мод уже належить іншій збірці'));updateModMetadata(added.id,{ownerProfileId:draft.id});setLib(updated);if(!draft.modIds.includes(added.id))update({modIds:[...draft.modIds,added.id]});setNotice(t('Мод додано до збірки'))});
const modEditor=()=>!draft?null:<div className="hf-mod-editor"><div className="hf-mod-panel"><h3>{t('Бібліотека модів')}</h3><input aria-label={t('Пошук модів')} placeholder={t('Пошук модів...')} value={modEditorSearch} onChange={e=>setModEditorSearch(e.target.value)}/><select aria-label={t('Категорія')} value={modEditorFilter} onChange={e=>setModEditorFilter(e.target.value)}><option value="Усі">{t('Усі категорії')}</option>{modCategories.map(c=><option key={c} value={c}>{t(c)}</option>)}</select><div className="hf-mod-scroll">{visibleGlobalMods.filter(m=>m.name.toLowerCase().includes(modEditorSearch.toLowerCase())&&(modEditorFilter==='Усі'||(modMetadata[m.id]?.category||'Інше')===modEditorFilter)).map(m=><div className="hf-mod-entry" key={m.id}><span title={m.name}>{m.name}<small>{t(modMetadata[m.id]?.category||'Інше')}</small></span><button type="button" disabled={draft.modIds.includes(m.id)} onClick={()=>toggleMod(m.id)} title={t('Додати')}>{draft.modIds.includes(m.id)?'✓':'+'}</button></div>)}</div></div><div className="hf-mod-panel"><h3>{t('Моди у збірці')} ({draft.modIds.length})</h3><div className="hf-mod-scroll">{draft.modIds.map((id,i)=>{const m=lib.mods.find(x=>x.id===id);if(!m)return <div className="hf-mod-entry" key={id}>{t('Файл відсутній')}: {id}<button onClick={()=>toggleMod(id)}>×</button></div>;return <div className="hf-mod-entry" key={id} draggable onDragStart={e=>e.dataTransfer.setData('text/hellforge-mod',id)} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();const dragged=e.dataTransfer.getData('text/hellforge-mod');if(!dragged||dragged===id)return;const ids=[...draft.modIds];ids.splice(ids.indexOf(dragged),1);ids.splice(ids.indexOf(id),0,dragged);update({modIds:ids})}}><span title={m.name}>{i+1}. {m.name}<small>{modMetadata[id]?.ownerProfileId===draft.id?t('Мод цієї збірки'):t(modMetadata[id]?.category||'Інше')}</small></span><button type="button" disabled={i===0} title={t('Вище')} onClick={()=>move(id,-1)}>↑</button><button type="button" disabled={i===draft.modIds.length-1} title={t('Нижче')} onClick={()=>move(id,1)}>↓</button><button type="button" title={t('Вилучити зі збірки')} onClick={()=>toggleMod(id)}>×</button></div>})}</div><div className="hf-private-import"><button type="button" onClick={()=>revealFolder('profile_mod')} title={t('Відкрити папку')}><FolderOpen size={15}/></button><button type="button" onClick={addPrivateMod}>+ {t('Додати одноразовий мод')}</button><small>{t('Прив’язаний до цієї збірки. Файл не з’являється в загальній бібліотеці.')}</small></div></div></div>;
const [modSettingsLoaded,setModSettingsLoaded]=useState(false);
const modSettingsReady=useRef(false);
const modSettingsLast=useRef('');
useEffect(()=>{
 let active=true;
 invoke<string|null>('get_mod_library_settings').then(raw=>{
  if(!active)return;
  if(raw){try{const data=JSON.parse(raw);if(data&&typeof data==='object'){
   if(data.metadata&&typeof data.metadata==='object'&&!Array.isArray(data.metadata))setModMetadata(data.metadata);
   if(Array.isArray(data.categories))setModCategories(Array.from(new Set([...DEFAULT_MOD_CATEGORIES,...data.categories.filter((x:unknown)=>typeof x==='string')])));
   if(typeof data.groupView==='boolean')setModGroupView(data.groupView);
   modSettingsLast.current=raw;
  }}catch{}}
  modSettingsReady.current=true;setModSettingsLoaded(true);
 }).catch(()=>{if(active)modSettingsReady.current=true});
 return()=>{active=false};
},[]);
useEffect(()=>{
 if(!modSettingsReady.current)return;
 const payload=JSON.stringify({metadata:modMetadata,categories:modCategories,groupView:modGroupView});
 if(payload===modSettingsLast.current)return;
 const timer=setTimeout(()=>{invoke('save_mod_library_settings',{payload}).then(()=>{modSettingsLast.current=payload}).catch(e=>console.error('Could not save mod settings:',e))},250);
 return()=>clearTimeout(timer);
},[modMetadata,modCategories,modGroupView,modSettingsLoaded]);
const tabRef=useRef(tab);tabRef.current=tab;
const t=(key:string)=>language==='uk'?key:(MOD_LIBRARY_LOCALES[language]?.[key]||USER_LOCALES[language]?.[key]||RELEASE_STRINGS[language]?.[key]||PREFINAL_STRINGS[language]?.[key]||NEXT_LOCALE_STRINGS[language]?.[key]||ADVANCED_UI[language]?.[key]||EXTRA_UI[language]?.[key]||NEW_UI[language]?.[key]||OTHER[language]?.[key]||COMMUNITY_LOCALES[language]?.[key]||EN[key]||key);
const native=typeof window!=='undefined'&&'__TAURI_INTERNALS__' in window;
const call=async<T,>(command:string,args?:Record<string,unknown>):Promise<T>=>{if(!native)throw Error('Системні функції доступні лише в Tauri. Запустіть npm run tauri dev.');return invoke<T>(command,args)};
const renameItem=(kind:'mod'|'map',item:Mod)=>{setRenameTarget({kind,id:item.id,name:item.name});setRenameValue(item.name)};
const submitRename=async()=>{if(!renameTarget||!renameValue.trim()||busy)return;const target=renameTarget;const name=renameValue.trim();if(name===target.name){setRenameTarget(null);return;}setBusy(true);try{await action(async()=>{setLib(await call<Library>('rename_library_item',{kind:target.kind,id:target.id,name}));setNotice(t('Назву змінено'));setRenameTarget(null)})}finally{setBusy(false)}};

const revealFolder=(kind:'game'|'mod'|'map'|'cover'|'profile_mod')=>action(async()=>{await call('reveal_library_folder',{kind})});
const refresh=()=>call<Library>('get_library').then(setLib).catch(e=>setError(String(e)));
const refreshAchievements=()=>call<AchievementStats>('get_achievement_stats').then(setAchievementStats).catch(e=>setError(String(e)));
useEffect(()=>{if(!native)return;refresh();refreshAchievements();call<EngineInfo[]>('list_engines').then(setEngines).catch(()=>{});let unlisten:(()=>void)|undefined;let mounted=true;listen<{profileId:string;state:string;detail?:string}>('hellforge-launch',event=>{if(!mounted)return;const v=event.payload;setLaunch({id:v.profileId,state:v.state,detail:v.detail});if(v.state==='exited'||v.state==='error'){refresh();refreshAchievements()}if(v.state==='exited'||v.state==='error')setLogs(p=>[new Date().toLocaleString()+' · '+(v.detail||v.state),...p]);}).then(fn=>{if(mounted)unlisten=fn;else fn()}).catch(e=>setError(String(e)));return()=>{mounted=false;unlisten?.()};},[]);
const action=async(f:()=>Promise<void>)=>{setError('');setNotice('');try{await f()}catch(e){setError(String(e))}};
const pick=async(filters:{name:string;extensions:string[]}[])=>{if(!native)throw Error('Імпорт доступний у desktop-застосунку');const result=await open({multiple:false,directory:false,filters});return typeof result==='string'?result:null};
const importFile=(kind:'game'|'mod'|'map')=>action(async()=>{const path=await pick([{name:kind==='game'?'IWAD':kind==='map'?'Map files':'Mod files',extensions:kind==='game'?['wad']:['wad','pk3','pk7','zip']}]);if(path){setLib(await call<Library>(kind==='game'?'import_game':'import_mod',{path,kind}));setNotice('Файл додано до бібліотеки')}});
const exportBundle=(p:Profile)=>action(async()=>{const path=await saveDialog({title:'Export Hellforge profile',defaultPath:p.name.replace(/[\\/:*?"<>|]/g,'_')+'.hellforge.zip',filters:[{name:'Hellforge bundle',extensions:['zip']}]});if(typeof path==='string'){await call<string>('export_profile',{id:p.id,path});setNotice('Збірку експортовано без комерційного IWAD і рушія')}});
const importBundle=()=>action(async()=>{const path=await pick([{name:'Hellforge bundle',extensions:['zip']}]);if(path){setLib(await call<Library>('import_profile_bundle',{path}));setNotice('Збірку імпортовано. Вибери рушій у налаштуваннях збірки.')}});
const backupData=()=>action(async()=>{const path=await saveDialog({title:'Зберегти резервну копію Hellforge',defaultPath:'hellforge-library-backup.json',filters:[{name:'JSON',extensions:['json']}]});if(typeof path==='string'){await call<string>('backup_library',{path});setNotice('Резервну копію створено')}});
const restoreData=()=>action(async()=>{const path=await pick([{name:'Hellforge JSON backup',extensions:['json']}]);if(path){if(!window.confirm('Замінити поточну бібліотеку резервною копією? Попередній стан буде збережено у AppData.'))return;setLib(await call<Library>('restore_library',{path}));setNotice('Бібліотеку відновлено')}});
const showHistory=(p:Profile)=>action(async()=>{setHistoryProfile(p.name);setHistory(await call('get_play_history',{profileId:p.id}));});
const inspectWad=(g:Game)=>action(async()=>{const d=await call<{format:string;lumps:number;maps:string[];titlepic:boolean}>('inspect_wad',{path:g.path});setWadInfo({...d,name:g.name})});
const installEngine=(kind:string)=>action(async()=>{setInstallingEngine(kind);try{const result=await call<EngineInfo>('install_engine',{kind});setEngines(await call<EngineInfo[]>('list_engines'));setNotice(result.name+' '+result.version+' '+t('встановлено'))}finally{setInstallingEngine(null)}});
const chooseEngine=()=>action(async()=>{const path=await pick([{name:'Windows executable',extensions:['exe']}]);if(path){setEngines(await call<EngineInfo[]>('register_engine',{path,name:engineName}));setNotice(t('Рушій додано до бібліотеки'));setEngineName('')}});
const removeEngine=(path:string)=>action(async()=>{setEngines(await call<EngineInfo[]>('unregister_engine',{path}));setNotice(t('Рушій вилучено з бібліотеки'))});
const refreshCovers=()=>action(async()=>{setBusy(true);try{setLib(await call<Library>('refresh_game_covers'));setNotice(t('Обкладинки оновлено'))}finally{setBusy(false)}});
const customGameCover=(id:string)=>action(async()=>{const path=await pick([{name:'Cover',extensions:['png','jpg','jpeg','webp']}]);if(path)setLib(await call<Library>('save_game_cover',{gameId:id,path}))});
const start=(id:string)=>action(async()=>{setLaunch({id,state:'starting'});try{const msg=await call<string>('launch_profile',{id});setLogs(p=>[new Date().toLocaleString()+' · '+msg,...p])}catch(e){setLaunch({id,state:'error',detail:String(e)});throw e}});
const create=()=>{if(!lib.games.length){setTab('Ігри');setError('Спочатку імпортуйте IWAD');return;}setDraft({id:uid(),name:'Нова збірка',gameId:lib.games[0].id,enginePath:engines[0]?.path||'',modIds:[],mapIds:[],extraArgs:[]});setTab('Головна')};
const save=()=>action(async()=>{if(!draft)return;const result=await call<Library>('save_profile',{profile:draft});setDraft(null);setLib(result);setNotice('Збірку збережено')});
const update=(patch:Partial<Profile>)=>setDraft(p=>p?{...p,...patch}:p);
const toggleMod=(id:string,kind:"mod"|"map"="mod")=>{if(!draft)return;const key=kind==="map"?"mapIds":"modIds";const ids=draft[key]||[];update({[key]:ids.includes(id)?ids.filter(x=>x!==id):[...ids,id]})};
const move=(id:string,dir:number,kind:"mod"|"map"="mod")=>{if(!draft)return;const key=kind==="map"?"mapIds":"modIds";const a=[...(draft[key]||[])],i=a.indexOf(id),j=i+dir;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];update({[key]:a})};
const formatTime=(seconds:number)=>{const h=Math.floor(seconds/3600),m=Math.floor((seconds%3600)/60);return h?`${h} год ${m} хв`:`${m} хв`};
const matches=(s:string)=>s.toLowerCase().includes(search.toLowerCase());
const groups=useGroups?Array.from(new Set([...lib.profiles.map(p=>p.group).filter((g):g is string=>!!g),'Без групи'])):['Без групи'];
const sortedProfiles=[...lib.profiles].filter(p=>matches(p.name)).sort((a,b)=>sort==='time'?(b.playSeconds||0)-(a.playSeconds||0):sort==='mods'?b.modIds.length-a.modIds.length:a.name.localeCompare(b.name));
const addGroup=()=>{const name=newGroup.trim();if(!name||!draft)return;update({group:name});setNewGroup('')};
const changeGroup=(p:Profile,group:string)=>action(async()=>{setLib(await call<Library>('save_profile',{profile:{...p,group:group==='Без групи'?null:group}}))});
useEffect(()=>{if(!native)return;let stop:(()=>void)|undefined;listen<{paths:string[]}>('tauri://drag-drop',event=>{const paths=event.payload.paths||[];const section=tabRef.current;action(async()=>{for(const path of paths){if(!/\.(wad|pk3|pk7|zip)$/i.test(path))continue;if(section==='Ігри'){if(/\.wad$/i.test(path))await call('import_game',{path});}else await call('import_mod',{path,kind:section==='Мапи'?'map':'mod'});}setLib(await call<Library>('get_library'));setNotice('Імпорт завершено')})}).then(fn=>stop=fn).catch(()=>{});return()=>stop?.()},[]);
const onFileDrop=(e:React.DragEvent)=>{e.preventDefault();setDragging(false);const paths=Array.from(e.dataTransfer.files).map(f=>(f as File&{path?:string}).path).filter((v):v is string=>!!v);if(!paths.length){setError('Windows drag-and-drop: шлях файлу недоступний. Використай кнопку імпорту.');return;}action(async()=>{for(const path of paths){const ext=path.split('.').pop()?.toLowerCase();if(['wad','pk3','pk7','zip'].includes(ext||'')){if(tab==='Ігри'){if(ext==='wad')await call('import_game',{path})}else await call('import_mod',{path,kind:tab==='Мапи'?'map':'mod'});}}await refresh();setNotice('Файли імпортовано')})};
const markCompleted=(id:string,completed:boolean)=>action(async()=>{setAchievementStats(await call<AchievementStats>('set_profile_completed',{profileId:id,completed}))});
const removeItem=(kind:'game'|'mod'|'map',id:string)=>{const item=kind==='game'?lib.games.find(x=>x.id===id):kind==='map'?lib.maps.find(x=>x.id===id):lib.mods.find(x=>x.id===id);if(item)setDeleteTarget({kind,id,name:item.name})};
const completedCount=achievementStats.completedProfiles.filter(id=>lib.profiles.some(p=>p.id===id)).length;
const totalHours=achievementStats.totalSeconds/3600;
const hourNames:Record<number,[string,string]>={1:['Пробудження морпіха', 'Проведи в DOOM-збірках свою першу годину.'],5:['Пекельна зміна', 'Награй загалом п’ять годин.'],10:['Нічний вартовий', 'Проведи десять годин у битвах.'],20:['Без права на відпочинок', 'Награй двадцять годин.'],50:['Загартований у пеклі', 'Награй п’ятдесят годин.'],100:['Легенда UAC', 'Проведи сто годин у збірках.']};
const modNames:Record<number,[string,string]>={1:['Перший артефакт', 'Імпортуй свій перший мод.'],5:['Зброяр', 'Збери бібліотеку з п’яти модів.'],10:['Арсенал руйнації', 'Імпортуй десять модів.'],25:['Колекціонер хаосу', 'Збери двадцять п’ять модів.']};
const mapNames:Record<number,[string,string]>={1:['Нова територія', 'Додай першу мапу.'],5:['Слідами картографа', 'Додай п’ять мап.'],10:['Архітектор лабіринтів', 'Додай десять мап.']};
const profileNames:Record<number,[string,string]>={1:['Іскра творіння', 'Створи першу збірку.'],5:['Майстерня пекла', 'Створи п’ять збірок.'],10:['Повелитель конфігурацій', 'Створи десять збірок.']};
const completedNames:Record<number,[string,string]>={1:['Місію виконано', 'Познач першу збірку як пройдену.'],10:['Винищувач кампаній', 'Заверши десять збірок.'],50:['Нескінченний похід', 'Заверши п’ятдесят збірок.']};
const launchNames:Record<number,[string,string]>={10:['Повернення в бій', 'Запусти збірки десять разів.'],50:['Завсідник порталу', 'Запусти збірки п’ятдесят разів.'],100:['Вічний перезапуск', 'Запусти збірки сто разів.']};
const achievementDesc=(kind:number,n:number)=> (ACHIEVEMENT_DESCRIPTIONS[language]||ACHIEVEMENT_DESCRIPTIONS.uk)[kind].replace('{n}',String(n));
const achievements=[
 {category:t('Дослідження та час гри'),items:[
  {id:'first',name:t('Перші кроки'),description:t('Запусти свою першу збірку.'),value:achievementStats.totalLaunches,target:1},
  {id:'explorer',name:t('Дослідник'),description:t('Запусти 5 різних збірок.'),value:achievementStats.distinctPlayed,target:5},
  ...[1,5,10,20,50,100].map(h=>({id:'hours'+h,name:t(hourNames[h][0]),description:achievementDesc(0,h),value:totalHours,target:h}))]},
 {category:t('Бібліотека'),items:[
  ...[1,5,10,25].map(n=>({id:'mods'+n,name:t(modNames[n][0]),description:achievementDesc(1,n),value:lib.mods.length,target:n})),
  ...[1,5,10].map(n=>({id:'maps'+n,name:t(mapNames[n][0]),description:achievementDesc(2,n),value:lib.maps.length,target:n})),
  ...[1,5,10].map(n=>({id:'profiles'+n,name:t(profileNames[n][0]),description:achievementDesc(3,n),value:lib.profiles.length,target:n}))]},
 {category:t('Прогрес і запуски'),items:[
  ...[1,10,50].map(n=>({id:'completed'+n,name:t(completedNames[n][0]),description:achievementDesc(4,n),value:completedCount,target:n})),
  ...[10,50,100].map(n=>({id:'launches'+n,name:t(launchNames[n][0]),description:achievementDesc(5,n),value:achievementStats.totalLaunches,target:n})),
  {id:'successful',name:t('Чистий вихід'),description:t('Заверши гру з кодом виходу 0.'),value:achievementStats.successfulSessions,target:1}
 ]}];
const allAchievements=achievements.flatMap(a=>a.items);const unlocked=allAchievements.filter(a=>a.value>=a.target).length;
return <div className={`app theme-${theme}`} onDragOver={e=>{if(e.dataTransfer.types.includes('text/hellforge-profile'))return;e.preventDefault();setDragging(true)}} onDragLeave={e=>{if(!e.currentTarget.contains(e.relatedTarget as Node))setDragging(false)}} onDrop={e=>{if(e.dataTransfer.types.includes('text/hellforge-profile')){e.preventDefault();setDragging(false);return}onFileDrop(e)}}>{dragging&&<div className="drop-overlay">{tab==='Ігри'?'Відпусти IWAD, щоб додати гру':tab==='Мапи'?'Відпусти файли, щоб додати мапи':'Відпусти файли, щоб додати моди'}</div>}<aside><div className="brand"><img className="brand-logo" src={emblem} alt="Hellforge emblem"/><img className="brand-wordmark" src={wordmark} alt="Hellforge"/></div><nav>{nav.map(([name,Icon])=><button key={name} className={tab===name?'active':''} onClick={()=>{setTab(name);setDraft(null);setError('')}}><Icon size={18}/>{t(name)}</button>)}</nav><div className="sidebar-bottom"><Flame size={16}/> {t("FORGE YOUR GAME")}</div></aside><main><header><div className="topsearch"><Search size={16}/><input placeholder={t("Пошук ігор, модів, збірок...")} value={search} onChange={e=>setSearch(e.target.value)}/></div><span className="status">{tab==='Ігри'?lib.games.length+' ' +t('Ігор'):tab==='Моди'?lib.mods.length+' ' +t('Модів'):tab==='Мапи'?lib.maps.length+' ' +t('Мап'):tab==='Рушії'?engines.length+' ' +t('Рушіїв'):tab==='Головна'?lib.profiles.length+' ' +t('Збірок'): 'HELLFORGE'}</span></header><section className="content">{launch&&<div className="launch-overlay" role="status" aria-live="polite"><div className="launch-panel"><img className="launch-wordmark" src={wordmark} alt="HELLFORGE — Classic FPS Launcher"/><h2>{launch.state==='starting'?t('Підготовка запуску…'):launch.state==='started'?t('Гру запущено'):launch.state==='error'?t('Помилка запуску'):'Гру завершено'}</h2><p>{launch.state==='starting'?t('Перевіряємо файли та запускаємо рушій.'):launch.state==='started'?t('Вікно гри має з’явитися незабаром. Можеш закрити це повідомлення.'):launch.detail||t('Процес гри завершився.')}</p>{launch.state==='starting'&&<div className="launch-progress"/>}<button className="primary" onClick={()=>setLaunch(null)}>{launch.state==='starting'?t('Приховати'):'Зрозуміло'}</button></div></div>}{error&&<div className="alert">{error}<button onClick={()=>setError('')}>×</button></div>}{notice&&<div className="notice">{notice}<button onClick={()=>setNotice('')}>×</button></div>}
{tab==='Головна'&&<><div className="home-intro"><div><div className="eyebrow">{t("SANCTUM")}</div><h1>{t('Твої збірки')}</h1><p>{t('Вибери профіль і вирушай у гру.')}</p></div><div className="home-controls"><div className="hf-sort" onBlur={e=>{if(!e.currentTarget.contains(e.relatedTarget as Node))setSortOpen(false)}}><button type="button" className="hf-sort-trigger" aria-label={t('Сортування')} aria-haspopup="listbox" aria-expanded={sortOpen} onClick={()=>setSortOpen(v=>!v)}><SlidersHorizontal size={17}/><span>{t(sort==='time'?'За часом гри':sort==='mods'?'За кількістю модів':'За алфавітом')}</span><ChevronDown size={16}/></button>{sortOpen&&<div className="hf-sort-menu" role="listbox" aria-label={t('Сортування')}>{([['name','За алфавітом'],['time','За часом гри'],['mods','За кількістю модів']] as const).map(([v,label])=><button key={v} type="button" role="option" aria-selected={sort===v} className={sort===v?'selected':''} onClick={()=>{setSort(v);setSortOpen(false)}}>{t(label)}{sort===v&&<Check size={15}/>}</button>)}</div>}</div><button onClick={importBundle}><Download size={16}/> Імпорт збірки</button><button onClick={()=>setCompact(v=>!v)}>{compact?"Картки":"Список"}</button><button className="primary" onClick={create}><Plus size={17}/>{t('Нова збірка')}</button></div></div>{groups.filter(group=>group==='Без групи'||lib.profiles.some(p=>p.group===group)).map(group=><div className="profile-group" key={group} onDragOver={e=>{e.preventDefault();e.stopPropagation();e.currentTarget.classList.add('drop-target')}} onDragLeave={e=>e.currentTarget.classList.remove('drop-target')} onDrop={e=>{e.stopPropagation();e.preventDefault();e.currentTarget.classList.remove('drop-target');const id=e.dataTransfer.getData('text/hellforge-profile');const profile=lib.profiles.find(p=>p.id===id);if(profile)changeGroup(profile,group)}}>{useGroups&&<div className="group-title"><h2>{group==='Без групи'?t('Без групи'):group}</h2><span>{sortedProfiles.filter(p=>!useGroups||(p.group||'Без групи')===group).length}</span></div>}<div className="cards">{sortedProfiles.filter(p=>!useGroups||(p.group||'Без групи')===group).map(p=><div className={compact?"tile profile-tile compact-profile":"tile profile-tile"} key={p.id} draggable onDragStart={e=>{e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/hellforge-profile',p.id);e.dataTransfer.setData('text/plain',p.id)}}><div className="tile-art cover-art"><Cover path={p.coverPath}/></div><h3>{p.name}</h3><p>{lib.games.find(g=>g.id===p.gameId)?.name} · {p.modIds.length} {t('модів')}</p><p>{t('Награно')}: {formatTime(p.playSeconds||0)} · {p.launches||0} {t('запусків')}</p><div className="tile-actions"><button className="small-primary" onClick={()=>start(p.id)}><Play size={14}/>{t('Грати')}</button><button className="profile-gear" title={t('Налаштування збірки')} aria-label={t('Налаштування збірки')} onClick={()=>setDraft({...p})}><Settings size={17}/></button></div></div>)}{!sortedProfiles.some(p=>!useGroups||(p.group||'Без групи')===group)&&<div className="group-empty">{t('Перетягни сюди збірку')}</div>}</div></div>)}{draft&&<div className="editor-overlay" onClick={()=>setDraft(null)}><div className="editor-modal" onClick={e=>e.stopPropagation()}><div className="modal-top"><h2>{t('Редактор збірки')}</h2><button onClick={()=>setDraft(null)}>×</button></div><label>{t('Назва збірки')}<input value={draft.name} onChange={e=>update({name:e.target.value})}/></label><label>{t('Гра / IWAD')}<select value={draft.gameId} onChange={e=>update({gameId:e.target.value})}>{lib.games.map(g=><option key={g.id} value={g.id}>{g.name}</option>)}</select></label><label>{t('Engine from library')}<select value={draft.enginePath} onChange={e=>update({enginePath:e.target.value})}><option value="">{t('Select engine')}</option>{engines.map(e=><option key={e.path} value={e.path}>{e.name} {e.version}</option>)}</select></label><h3>{t('Моди та порядок завантаження')}</h3>{modEditor()}<label>{t('Map (optional)')}<select value={draft.mapIds?.[0]||''} onChange={e=>update({mapIds:e.target.value?[e.target.value]:[]})}><option value="">{t('No map')}</option>{lib.maps.map(m=><option key={m.id} value={m.id}>{m.name}</option>)}</select></label>{useGroups&&<label>{t('Група')}<select value={draft.group||'Без групи'} onChange={e=>update({group:e.target.value==='Без групи'?null:e.target.value})}>{groups.map(g=><option key={g} value={g}>{g==='Без групи'?t(g):g}</option>)}{draft.group&&!groups.includes(draft.group)&&<option value={draft.group}>{draft.group}</option>}</select></label>} {useGroups&&<div className="group-create"><input value={newGroup} onChange={e=>setNewGroup(e.target.value)} placeholder={t('Назва нової групи')}/><button onClick={addGroup} disabled={!newGroup.trim()}><Plus size={16}/>{t('Створити групу')}</button></div>}<label>{t('Додаткові аргументи (по одному на рядок)')}<textarea value={draft.extraArgs.join('\n')} onChange={e=>update({extraArgs:e.target.value.split('\n').filter(Boolean)})}/></label><div className="cover-buttons"><button onClick={()=>action(async()=>{if(!lib.profiles.some(p=>p.id===draft.id))throw Error(t('Спочатку збережи збірку'));const path=await pick([{name:'Cover',extensions:['png','jpg','jpeg','webp']}]);if(path){await call('save_cover',{profileId:draft.id,path});const updated=await call<Library>('get_library');setLib(updated);setDraft(updated.profiles.find(p=>p.id===draft.id)||null)}})}>{t('Вибрати обкладинку')}</button><button disabled={busy} onClick={()=>action(async()=>{if(!lib.profiles.some(p=>p.id===draft.id))throw Error(t('Спочатку збережи збірку'));setBusy(true);try{const updated=await call<Library>('fetch_profile_cover',{profileId:draft.id});setLib(updated);setDraft(updated.profiles.find(p=>p.id===draft.id)||null);setNotice(t('Обкладинку оновлено'))}finally{setBusy(false)}})}><Download size={15}/>{t('Знайти обкладинку SteamGridDB')}</button></div><div className="actions"><button className="primary" onClick={save}>{t('Зберегти')}</button>{lib.profiles.some(p=>p.id===draft.id)&&<button onClick={()=>exportBundle(draft)}><Download size={16}/> Експортувати збірку</button>}<button onClick={()=>setDraft(null)}>{t('Скасувати')}</button>{lib.profiles.some(p=>p.id===draft.id)&&<button className="danger" onClick={()=>setDeleteTarget({kind:'profile',id:draft.id,name:draft.name})}><Trash2 size={15}/>{t('Видалити')}</button>}</div></div></div>}</>}
{tab==='Ігри'&&<><div className="sectionhead"><div><div className="eyebrow">{t("LIBRARY")}</div><h1>{t("Бібліотека ігор")}</h1><p>{t("Імпортуй власні IWAD-файли DOOM, Heretic, Hexen та інших ігор.")}</p></div><div className="inputrow"><button disabled={busy} onClick={()=>action(async()=>{setBusy(true);try{setLib(await call<Library>("refresh_steamgrid_covers"));setNotice(t("Обкладинки оновлено"))}finally{setBusy(false)}})}>{t("SteamGridDB обкладинки")}</button><button onClick={()=>revealFolder('game')}><FolderOpen size={16}/>{t("Відкрити папку")}</button><button className="primary" onClick={()=>importFile('game')}><Plus size={17}/> {t("Add IWAD")}</button></div></div><div className="cards">{[...lib.games].sort((a,b)=>a.name.localeCompare(b.name,language)).filter(g=>matches(g.name)).map(g=><div className="tile" key={g.id}><div className="tile-art cover-art"><Cover path={g.coverPath} alt={g.name}/></div><h3>{g.name}</h3><p title={g.path}>{g.path.split(/[\\/]/).pop()}</p><span className="pill green">{t("Imported")}</span><button className="quiet" onClick={()=>inspectWad(g)}>{t("WAD info")}</button><button className="quiet" onClick={()=>customGameCover(g.id)}>{t("Change cover")}</button><button className="iconbutton" title={t("Видалити")} onClick={()=>removeItem('game',g.id)}><Trash2 size={17}/></button></div>)}{!lib.games.length&&<div className="empty"><FolderOpen size={34}/> {t("Бібліотека порожня. Додай оригінальний IWAD-файл.")}</div>}</div></>}
{tab==='Моди'&&<><div className="sectionhead"><div><div className="eyebrow">ARSENAL</div><h1>{t('Мої моди')}</h1><p>{t('Категорії, групування та організація бібліотеки.')}</p></div><div className="inputrow"><button onClick={()=>revealFolder('mod')}><FolderOpen size={16}/>{t('Відкрити папку')}</button><button className="primary" onClick={()=>importFile('mod')}><Plus size={17}/>{t('Імпорт мода')}</button></div></div><div className="hf-mod-toolbar"><button onClick={()=>{setModGroupView(v=>{localStorage.setItem('hf-mod-group-view',String(!v));return !v})}}>{t(modGroupView?'Показати списком':'Групувати моди')}</button><select value={modFilter} onChange={e=>setModFilter(e.target.value)}><option value="Усі">{t('Усі категорії')}</option>{modCategories.map(c=><option key={c} value={c}>{t(c)}</option>)}</select><input placeholder={t('Нова категорія')} value={newModCategory} onChange={e=>setNewModCategory(e.target.value)}/><button disabled={!newModCategory.trim()} onClick={()=>{const c=newModCategory.trim();if(!modCategories.includes(c))updateModCategories([...modCategories,c]);setNewModCategory('')}}>+ {t('Категорія')}</button></div><details className="hf-category-manager"><summary>{t('Керування категоріями')}</summary><div className="hf-category-manager-list">{modCategories.map((c,i)=><div className="hf-category-manager-row" key={c}>{editingModCategory===c?<><input aria-label={t('Нова назва категорії')} value={editedModCategoryName} onChange={e=>setEditedModCategoryName(e.target.value)}/><button onClick={()=>{const next=editedModCategoryName.trim();if(next&&!modCategories.includes(next)){updateModCategories(modCategories.map(x=>x===c?next:x));setModMetadata(prev=>{const out={...prev};Object.keys(out).forEach(id=>{if(out[id].category===c)out[id]={...out[id],category:next}});localStorage.setItem('hf-mod-metadata-v1',JSON.stringify(out));return out})}setEditingModCategory('')}}>✓</button><button onClick={()=>setEditingModCategory('')}>×</button></>:<><span>{t(c)}</span><button disabled={i===0} title={t('Вище')} onClick={()=>{const a=[...modCategories];[a[i-1],a[i]]=[a[i],a[i-1]];updateModCategories(a)}}>↑</button><button disabled={i===modCategories.length-1} title={t('Нижче')} onClick={()=>{const a=[...modCategories];[a[i+1],a[i]]=[a[i],a[i+1]];updateModCategories(a)}}>↓</button><button title="Перейменувати" onClick={()=>{setEditingModCategory(c);setEditedModCategoryName(c)}}><Pencil size={14}/></button></>}</div>)}</div></details>{selectedMods.length>0&&<div className="hf-bulk"><span>Вибрано: {selectedMods.length}</span><select defaultValue="" onChange={e=>{if(!e.target.value)return;selectedMods.forEach(id=>updateModMetadata(id,{category:e.target.value}));setSelectedMods([])}}><option value="">{t('Призначити категорію...')}</option>{modCategories.map(c=><option key={c} value={c}>{t(c)}</option>)}</select><button onClick={()=>setSelectedMods([])}>{t('Скасувати вибір')}</button></div>}{(modGroupView?(modFilter==='Усі'?modCategories:[modFilter]):['Усі']).map(category=>{const items=visibleGlobalMods.filter(m=>matches(m.name)&&(modFilter==='Усі'||(modMetadata[m.id]?.category||'Інше')===modFilter)&&(!modGroupView||(modMetadata[m.id]?.category||'Інше')===category));if(!items.length)return null;return <section className="hf-mod-group" key={category}>{modGroupView&&<h2>{category} <small>({items.length})</small></h2>}<div className="rows">{items.map(m=><div className="item" key={m.id} draggable onDragStart={e=>e.dataTransfer.setData('text/hellforge-mod-category',m.id)}><input aria-label="Вибрати мод" type="checkbox" checked={selectedMods.includes(m.id)} onChange={e=>setSelectedMods(prev=>e.target.checked?[...prev,m.id]:prev.filter(x=>x!==m.id))}/><div className="itemicon hf-mod-icon" title={modMetadata[m.id]?.category||'Інше'}><ModCategoryIcon category={modMetadata[m.id]?.category||'Інше'}/></div><div className="hf-mod-details"><strong title={m.name}>{m.name}</strong><small title={m.path}>{m.path}</small></div><select aria-label={t('Категорія')} value={modMetadata[m.id]?.category||'Інше'} onChange={e=>updateModMetadata(m.id,{category:e.target.value})}>{modCategories.map(c=><option key={c} value={c}>{t(c)}</option>)}</select><button className="iconbutton" title={t('Перейменувати')} onClick={()=>renameItem('mod',m)}><Pencil size={17}/></button><button className="iconbutton" title={t('Видалити')} onClick={()=>removeItem('mod',m.id)}><Trash2 size={17}/></button></div>)}</div></section>})}{modGroupView&&<div className="hf-category-drops">{modCategories.map(c=><div key={c} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();const id=e.dataTransfer.getData('text/hellforge-mod-category');if(id)updateModMetadata(id,{category:c})}}>{t(c)}</div>)}</div>}{!visibleGlobalMods.length&&<div className="empty">{t('Модів поки немає. Імпортуй файл, щоб почати.')}</div>}</>}
{tab==='Збірки'&&<><div className="sectionhead"><div><div className="eyebrow">{t("PROFILES")}</div><h1>{draft?t('Редактор збірки'):t('Мої збірки')}</h1><p>{t("Окремі конфігурації для кожної пригоди.")}</p></div><button className="primary" onClick={create}><Plus size={17}/> Forge Profile</button></div>{draft?<div className="editor"><label>{t("Назва збірки")}<input value={draft.name} onChange={e=>update({name:e.target.value})}/></label><label>{t("Гра / IWAD")}<select value={draft.gameId} onChange={e=>update({gameId:e.target.value})}>{lib.games.map(g=><option value={g.id} key={g.id}>{g.name}</option>)}</select></label><label>{t('Engine from library')}<select value={draft.enginePath} onChange={e=>update({enginePath:e.target.value})}><option value="">{t('Select engine')}</option>{engines.map(e=><option key={e.path} value={e.path}>{e.name} {e.version}</option>)}</select></label>{!engines.some(e=>e.path===draft.enginePath)&&draft.enginePath&&<p className="muted">{t('Engine not in library')}: {draft.enginePath}</p>}<h3>{t("Моди та порядок завантаження")}</h3>{modEditor()}<label>{t('Map (optional)')}<select value={draft.mapIds?.[0]||''} onChange={e=>update({mapIds:e.target.value?[e.target.value]:[]})}><option value="">{t('No map')}</option>{(lib.maps||[]).map(m=><option key={m.id} value={m.id}>{m.name}</option>)}</select></label><label>{t("Додаткові аргументи (по одному на рядок)")}<textarea rows={3} value={draft.extraArgs.join('\n')} onChange={e=>update({extraArgs:e.target.value.split('\n').filter(Boolean)})}/></label><div className="cover-editor"><h3>{t("Обкладинка (600 × 900)")}</h3><p className="muted">{t("PNG, JPG або WEBP. Рекомендований розмір 600×900, зображення адаптується до картки. Спочатку збережи збірку.")}</p><button onClick={()=>action(async()=>{if(!lib.profiles.some(p=>p.id===draft.id))throw Error('Спочатку збережи збірку');const path=await pick([{name:'Cover image',extensions:['png','jpg','jpeg','webp']}]);if(path){await call('save_cover',{profileId:draft.id,path});const updated=await call<Library>('get_library');setLib(updated);setDraft(updated.profiles.find(p=>p.id===draft.id)||null);setNotice(t('Обкладинку оновлено'))}})}><FolderOpen size={16}/> {t("Вибрати обкладинку")}</button></div><div className="actions"><button className="primary" onClick={save}>{t("Зберегти збірку")}</button><button onClick={()=>setDraft(null)}>{t("Скасувати")}</button></div></div>:<div className="rows">{lib.profiles.filter(p=>matches(p.name)).map(p=><div className="item" key={p.id}><div className="itemicon"><Layers/></div><div><strong>{p.name}</strong><small>{lib.games.find(g=>g.id===p.gameId)?.name} · {p.modIds.length} {t('модів')}</small></div><button className="quiet" onClick={()=>setDraft(p)}>{t("Редагувати")}</button><button className="small-primary" onClick={()=>start(p.id)}><Play size={14}/> {t("Грати")}</button><button className="iconbutton" title="Видалити" onClick={()=>action(async()=>{setDeleteTarget({kind:'profile',id:p.id,name:p.name})})}><Trash2 size={17}/></button></div>)}{!lib.profiles.length&&<div className="empty">{t("Профілів немає. Натисни Forge Profile.")}</div>}</div>}</>}
{tab==='Рушії'&&<><div className="sectionhead"><div><div className="eyebrow">{t("SOURCE PORTS")}</div><h1>{t('Engines')}</h1><p>{t('Engine library description')}</p></div></div><div className="editor"><h3>{t('Add engine')}</h3><div className="inputrow"><input value={engineName} onChange={e=>setEngineName(e.target.value)} placeholder={t('Engine name optional')}/><button className="primary" onClick={chooseEngine}><Plus size={16}/>{t('Add EXE')}</button></div><div className="engine-install-grid">{(['gzdoom','lzdoom','dsda'] as const).map(kind=><button className="primary" key={kind} disabled={installingEngine!==null} onClick={()=>installEngine(kind)}><Download size={16}/>{installingEngine===kind?t('Installing'):t('Install')+' '+({gzdoom:'GZDoom',lzdoom:'LZDoom',dsda:'DSDA-Doom'}[kind])}</button>)}</div><h3>{t('Installed engines')}</h3><div className="rows">{engines.map(e=><div className="item" key={e.path}><Cpu size={20}/><div><strong>{e.name} {e.version}</strong><small>{e.path}</small></div><button title={t('Remove from library')} onClick={()=>removeEngine(e.path)}><Trash2 size={16}/></button></div>)}{!engines.length&&<div className="empty">{t('No engines')}</div>}</div></div></>}
{tab==='Мапи'&&<><div className="sectionhead"><div><div className="eyebrow">{t("MAPS")}</div><h1>{t("Мапи")}</h1><p>{t("Окрема бібліотека мап і мегавадiв. Підключай їх у редакторі збірки.")}</p></div><div className="inputrow"><button onClick={()=>revealFolder('map')}><FolderOpen size={16}/>{t("Відкрити папку")}</button><button className="primary" onClick={()=>importFile('map')}><Plus size={17}/> {t("Імпорт мапи")}</button></div></div><div className="rows">{(lib.maps||[]).filter(m=>matches(m.name)).map(m=><div className="item" key={m.id}><div className="itemicon"><FolderOpen/></div><div><strong>{m.name}</strong><small>{m.path}</small></div><button className="iconbutton" title={t("Перейменувати")} onClick={()=>renameItem('map',m)}><Pencil size={17}/></button><button className="iconbutton" title={t("Видалити")} onClick={()=>removeItem('map',m.id)}><Trash2 size={17}/></button></div>)}{!(lib.maps||[]).length&&<div className="empty">{t("Мап поки немає.")}</div>}</div></>}
{tab==='Генератор мап'&&<><div className="sectionhead"><div><div className="eyebrow">{t("OBSIDIAN LEVEL MAKER")}</div><h1>{t('Генератор мап')}</h1><p>{t('Створюй випадкові рівні DOOM за допомогою OBSIDIAN.')}</p></div></div><div className="editor"><h3>{t('Підключення OBSIDIAN')}</h3><p className="muted">{t('Встанови OBSIDIAN окремо та вибери його виконуваний файл. Налаштуй генерацію в Hellforge. Початковий CONFIG.txt OBSIDIAN буде відновлено після запуску.')}</p><div className="inputrow"><input readOnly value={obsidianExe} placeholder="OBSIDIAN.exe"/><button onClick={()=>action(async()=>{const path=await pick([{name:'Windows executable',extensions:['exe']}]);if(path){setObsidianExe(path);localStorage.setItem('hf-obsidian-exe',path)}})}>{t('Вибрати EXE')}</button></div><label>{t('Назва згенерованої мапи')}<input value={obsidianName} maxLength={80} onChange={e=>setObsidianName(e.target.value)}/></label><div className="obsidian-options">{([['game','Гра',[['doom2','DOOM II'],['doom1','DOOM'],['tnt','TNT: Evilution'],['plutonia','Plutonia']]],['length','Кількість рівнів',[['single','Один'],['few','Кілька'],['episode','Епізод'],['game','Повна кампанія']]],['theme','Тематика',[['original','Автоматична (OBSIDIAN v20)']]],['outdoors','Відкриті простори',[['none','Немає'],['few','Мало'],['some','Помірно'],['heaps','Багато'],['mixed','Змішано']]],['bosses','Боси',[['none','Немає'],['minor','Мало'],['medium','Помірно'],['mixed','Змішано']]]] as const).map(([key,label,options])=><label key={key}>{t(label)}<select value={obsidianSettings[key]} onChange={e=>setObsidianSettings(v=>({...v,[key]:e.target.value}))}>{options.map(([value,title])=><option key={value} value={value}>{t(title)}</option>)}</select></label>)}</div><details className="obsidian-advanced"><summary>{t('Розширені налаштування генерації')}</summary><p className="muted">{t('Параметри OBSIDIAN v20. Початкова конфігурація відновлюється після генерації.')}</p><div className="obsidian-options">{([['caves','Печери'],['liquids','Рідини'],['hallways','Коридори'],['teleporters','Телепорти'],['steepness','Перепади висоти'],['secrets','Секрети']] as const).map(([key,label])=><label key={key}>{t(label)}<select value={obsidianSettings[key]} onChange={e=>setObsidianSettings(v=>({...v,[key]:e.target.value}))}>{([['none','Немає'],['few','Мало'],['some','Помірно'],['heaps','Багато'],['mixed','Змішано']] as const).map(([value,title])=><option key={value} value={value}>{t(title)}</option>)}</select></label>)}{([['health','Здоров’я'],['ammo','Боєприпаси'],['weapons','Зброя'],['items','Предмети']] as const).map(([key,label])=><label key={key}>{t(label)}<select value={obsidianSettings[key]} onChange={e=>setObsidianSettings(v=>({...v,[key]:e.target.value}))}>{([['scarce','Дефіцит'],['less','Менше'],['normal','Нормально'],['more','Більше'],['heaps','Багато']] as const).map(([value,title])=><option key={value} value={value}>{t(title)}</option>)}</select></label>)}{([['float_size','Розмір мапи',[['20','Маленька'],['36','Середня'],['55','Велика'],['75','Величезна']]],['float_mons','Кількість монстрів',[['0.5','Мало'],['1','Нормально'],['1.5','Багато'],['2','Дуже багато']]],['float_strength','Сила монстрів',[['0.5','Легше'],['1','Нормально'],['1.5','Складніше'],['2','Екстремально']]]] as const).map(([key,label,opts])=><label key={key}>{t(label)}<select value={obsidianSettings[key]} onChange={e=>setObsidianSettings(v=>({...v,[key]:e.target.value}))}>{opts.map(([value,title])=><option key={value} value={value}>{t(title)}</option>)}</select></label>)}</div></details><div className="actions"><button className="primary" disabled={!obsidianExe||obsidianBusy||!obsidianName.trim()} onClick={()=>action(async()=>{setObsidianBusy(true);try{const updated=await call<Library>('generate_obsidian_map',{exePath:obsidianExe,name:obsidianName.trim(),settings:obsidianSettings});setLib(updated);setNotice(t('Мапу згенеровано та додано до бібліотеки'));setTab('Мапи')}finally{setObsidianBusy(false)}})}><Flame size={17}/>{obsidianBusy?t('Генерація…'):t('Згенерувати WAD')}</button><button onClick={()=>setTab('Мапи')}>{t('Відкрити бібліотеку мап')}</button></div><p className="muted">{t('Під час генерації інтерфейс залишається доступним. Результат імпортується як мапа.')}</p></div></>}
{tab==='Налаштування'&&<><div className="sectionhead"><div><div className="eyebrow">{t("CONFIGURATION")}</div><h1>{t("Налаштування")}</h1></div></div><div className="editor"><h3>Hellforge</h3><label>{t("Мова інтерфейсу")}<select value={language} onChange={e=>{setLanguage(e.target.value);localStorage.setItem('hellforge-language-major',e.target.value)}}><option value="uk">Українська</option><option value="en">English</option><option value="pl">Polski</option><option value="de">Deutsch</option><option value="fr">Français</option><option value="es">Español</option><option value="ja">日本語</option><option value="zh">简体中文</option><option value="cs">Čeština</option><option value="sk">Slovenčina</option><option value="bg">Български</option><option value="hr">Hrvatski</option><option value="sr">Српски</option><option value="ro">Română</option><option value="be">Беларуская</option><option value="lt">Lietuvių</option><option value="lv">Latviešu</option><option value="et">Eesti</option><option value="ka">ქართული</option><option value="kk">Қазақша</option><option value="uz">Oʻzbekcha</option><option value="az">Azərbaycanca</option><option value="hy">Հայերեն</option></select></label><label>{t("Тема")}<select value={theme} onChange={e=>{setTheme(e.target.value);localStorage.setItem('hellforge-theme-major',e.target.value)}}><option value="obsidian">Obsidian Dark</option><option value="ember">Ember Red</option><option value="steel">Cold Steel</option><option value="light">Ash Light</option><option value="amethyst">Amethyst Night</option><option value="forest">Forest Relic</option><option value="midnight">Midnight Blue</option></select></label><label className="hf-toggle"><input type="checkbox" checked={useGroups} onChange={e=>{setUseGroups(e.target.checked);localStorage.setItem('hf-use-groups',String(e.target.checked))}}/> {t('Групувати збірки')}</label><label>SteamGridDB API key<input type="password" value={sgKey} onChange={e=>setSgKey(e.target.value)} placeholder="API key"/></label><button onClick={()=>action(async()=>{await call("save_steamgrid_key",{key:sgKey});setNotice(t("Ключ SteamGridDB збережено"))})}>{t("Зберегти ключ SteamGridDB")}</button><div className="backup-panel"><h3>{t("Бібліотека SQLite")}</h3><p className="muted">{t("Бібліотека Hellforge зберігається у SQLite. Резервна копія містить метадані та налаштування, але не файли ігор і модів.")}</p><div className="inputrow"><button onClick={backupData}>{t("Експортувати резервну копію")}</button><button onClick={restoreData}>{t("Відновити резервну копію")}</button></div></div><button onClick={()=>setTab('Рушії')}>{t("Налаштувати рушій →")}</button></div></>}
{tab==='Досягнення'&&<><div className="sectionhead"><div><div className="eyebrow">{t("HALL OF GLORY")}</div><h1>{t('Досягнення')}</h1><p>{unlocked} / {allAchievements.length} · {t("Досягнення Hellforge, не ігрові Steam-досягнення")}</p></div><button onClick={refreshAchievements}><Trophy size={16}/> {t("Оновити")}</button></div><div className="achievement-summary"><div><CheckCircle2/><span>{t("Відкрито")}</span><strong>{unlocked} / {allAchievements.length}</strong></div><div><Clock3/><span>{t("Награно годин")}</span><strong>{totalHours.toFixed(1)}</strong></div><div><Play/><span>{t("Запусків")}</span><strong>{achievementStats.totalLaunches}</strong></div><div><Target/><span>{t("Пройдених збірок")}</span><strong>{completedCount}</strong></div></div>{achievements.map(section=><div key={section.category} className="achievement-section"><h2>{section.category}</h2><div className="achievement-grid">{section.items.map(a=><div key={a.id} className={'achievement-card '+(a.value>=a.target?'unlocked':'')}><div className="achievement-icon">{a.value>=a.target?<Medal size={22}/>:<Star size={22}/>}</div><strong>{a.name}</strong><p>{a.description}</p><div className="achievement-progress"><div style={{width:`${Math.min(100,100*a.value/a.target)}%`}}/></div><small>{Math.min(a.value,a.target).toLocaleString('uk-UA',{maximumFractionDigits:1})} / {a.target}</small></div>)}</div></div>)}<div className="achievement-section"><h2>{t("Пройдені збірки")}</h2><p className="muted">{t("Позначай завершені збірки вручну.")}</p><div className="achievement-completions">{lib.profiles.map(p=><label key={p.id}><input type="checkbox" checked={achievementStats.completedProfiles.includes(p.id)} onChange={e=>markCompleted(p.id,e.target.checked)}/><span>{p.name}</span></label>)}{!lib.profiles.length&&<p>{t("Спочатку створи збірку.")}</p>}</div></div></>}
{tab==='Журнал'&&<><div className="sectionhead"><div><div className="eyebrow">{t("DIAGNOSTICS")}</div><h1>{t("Журнал запусків")}</h1></div></div><div className="editor">{logs.length?logs.map((l,i)=><p className="log" key={i}>{l}</p>):<p className="muted">{t("Поки немає запусків у цій сесії.")}</p>}</div><div className="editor"><h3>{t("Історія запусків (SQLite)")}</h3><div className="inputrow">{lib.profiles.map(p=><button key={p.id} onClick={()=>showHistory(p)}>{p.name}</button>)}</div>{historyProfile&&<><h4>{historyProfile}</h4>{history.length?history.map((h,i)=><p className="log" key={i}>{h.startedAt} · {formatTime(h.seconds)} · код: {h.exitCode??'—'}</p>):<p className="muted">{t("Запусків ще немає.")}</p>}</>}</div></>}
{renameTarget&&<div className="editor-overlay confirm-overlay" onMouseDown={e=>{if(e.target===e.currentTarget)setRenameTarget(null)}}><form className="confirm-dialog rename-dialog" role="dialog" aria-modal="true" aria-labelledby="rename-title" onSubmit={e=>{e.preventDefault();void submitRename()}}><div className="rename-dialog-header"><div className="rename-dialog-icon"><Pencil size={21}/></div><div><h2 id="rename-title">{t('Перейменувати')}</h2><p>{renameTarget.kind==='map'?t('Мапи'):t('Моди')}</p></div></div><label htmlFor="rename-value">{t('Нова назва')}</label><input id="rename-value" autoFocus maxLength={150} value={renameValue} onChange={e=>setRenameValue(e.target.value)} onKeyDown={e=>{if(e.key==='Escape')setRenameTarget(null)}} placeholder={t('Нова назва')}/><p className="rename-dialog-hint">{t('Зміниться лише назва в бібліотеці. Файл на диску залишиться без змін.')}</p><div className="actions"><button type="button" onClick={()=>setRenameTarget(null)}>{t('Скасувати')}</button><button className="primary" type="submit" disabled={!renameValue.trim()||busy}>{t('Зберегти')}</button></div></form></div>}{wadInfo&&<div className="editor-overlay confirm-overlay" onClick={()=>setWadInfo(null)}><div className="confirm-dialog" role="dialog" aria-modal="true" onClick={e=>e.stopPropagation()}><h2>{wadInfo.name}</h2><p>{wadInfo.format} · {wadInfo.lumps} lumps · {wadInfo.maps.length} maps · TITLEPIC: {wadInfo.titlepic?"Yes":"No"}</p><p className="muted">{wadInfo.maps.join(", ")||"No map markers found"}</p><button className="primary" onClick={()=>setWadInfo(null)}>OK</button></div></div>}{deleteTarget&&<div className="editor-overlay confirm-overlay" onClick={()=>setDeleteTarget(null)}><div className="confirm-dialog" role="dialog" aria-modal="true" onClick={e=>e.stopPropagation()}><Trash2 size={24}/><h2>{t('Підтвердити видалення')}</h2><p>{t('Видалити')} «{deleteTarget.name}»?</p><div className="actions"><button onClick={()=>setDeleteTarget(null)}>{t('Скасувати')}</button><button className="primary" onClick={()=>action(async()=>{const target=deleteTarget;if(!target)return;const result=await call<Library>(target.kind==='profile'?'delete_profile':'delete_library_item',target.kind==='profile'?{id:target.id}:{kind:target.kind,id:target.id});setLib(result);setDeleteTarget(null);if(target.kind==='profile')setDraft(null)})}>{t('Видалити')}</button></div></div></div>}</section><footer>HELLFORGE <span>v1.0.0</span></footer></main></div>}
